// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/health", wrapper.Health)
	router.GET(options.BaseURL+"/api/me", wrapper.GetMe)
	router.DELETE(options.BaseURL+"/api/houses/bind", wrapper.UnbindHouse)
	router.POST(options.BaseURL+"/api/houses/bind", wrapper.BindHouse)
	router.POST(options.BaseURL+"/api/auth/esia-mock", wrapper.EsiaMockLogin)
	router.GET(options.BaseURL+"/api/uk/queue", wrapper.ListUkQueue)
	router.POST(options.BaseURL+"/api/uk/events", wrapper.CreateUkEvent)
	router.GET(options.BaseURL+"/api/events", wrapper.ListEvents)
	router.GET(options.BaseURL+"/api/houses/suggest", wrapper.SuggestAddresses)
	router.GET(options.BaseURL+"/api/houses/:houseId/incidents", wrapper.ListHouseIncidents)
	router.GET(options.BaseURL+"/api/houses/:houseId/requests", wrapper.ListHouseRequests)
	router.GET(options.BaseURL+"/api/houses/:houseId/stats", wrapper.HouseStats)
	router.POST(options.BaseURL+"/api/incidents", wrapper.CreateIncident)
	router.POST(options.BaseURL+"/api/incidents/analyze", wrapper.AnalyzeIncident)
	router.POST(options.BaseURL+"/api/incidents/photos", wrapper.UploadStagedPhoto)
	router.GET(options.BaseURL+"/api/incidents/:id", wrapper.GetIncident)
	router.POST(options.BaseURL+"/api/incidents/:id/join", wrapper.JoinIncident)
	router.POST(options.BaseURL+"/api/incidents/:id/confirm", wrapper.ConfirmIncident)
	router.PATCH(options.BaseURL+"/api/incidents/:id/status", wrapper.SetIncidentStatus)
	router.POST(options.BaseURL+"/api/incidents/:id/photos", wrapper.UploadIncidentPhoto)
	router.GET(options.BaseURL+"/api/photos/:id", wrapper.GetPhoto)
}

